// Cases for the RegExp differential. Each entry: [category, pattern, flags, ...inputs].
// An input is a string, or { s: string, start: number } to begin at a given index (the flags then also get g, or y when given).
// record.js runs them under Node and writes expected.json; the engine tests replay expected.json without Node.
// Patterns use String.raw so backslashes read as they would in a regex literal.
const R = String.raw;
const cases = [];
const m = (cat, p, f, ...inputs) => cases.push([cat, p, f, ...inputs]);
const err = (p, f = '') => cases.push(['error', p, f]);

// ---- basics, alternation, captures -----------------------------------------------------------------------
m('basic', 'abc', '', 'xabcx', 'ab', '');
m('basic', '', '', 'abc', '');
m('basic', 'a|b|c', '', 'xxc', 'zzz');
m('basic', 'a|ab', '', 'abc');
m('basic', '(a)|(b)', '', 'b', 'a');
m('basic', R`((a)|(ab))((c)|(bc))`, '', 'abc');
m('basic', '(a)(b)?(c)', '', 'ac', 'abc');
m('basic', '(?:a)(b)', '', 'ab');
m('basic', '(a(b(c)))', '', 'abc');
m('basic', '()', '', 'x', '');
m('basic', '(|a)+', '', 'aaa');
m('basic', '.', '', '\n', '\r', '\u2028', 'x');
